def open_account(accounts, name, deposit=0):
    if name in accounts:
        return False
    accounts[name] = deposit
    return True

def deposit(accounts, name, amount):
    accounts[name] += amount
    return accounts[name]

def withdraw(accounts, name, amount):
    if amount > accounts[name]:
        return False
    accounts[name] -= amount
    return True

def transfer(accounts, from_name, to_name, amount):
    if not withdraw(accounts, from_name, amount):
        return False
    deposit(accounts, to_name, amount)
    return True

def statement(accounts):
    lines = []
    for name in sorted(accounts, key=lambda n: (-accounts[n], n)):
        lines.append(f"{name}: ${accounts[name]:.2f}")
    lines.append(f"Total: ${sum(accounts.values()):.2f}")
    return lines

def run(accounts, commands):
    output = []
    for command in commands:
        parts = command.split()
        action, args = parts[0], parts[1:]
        if action == "open":
            amount = float(args[1]) if len(args) > 1 else 0
            if open_account(accounts, args[0], amount):
                output.append(f"Opened {args[0]}")
            else:
                output.append(f"{args[0]} already exists")
        elif action == "show":
            output.extend(statement(accounts))
        elif action in ("deposit", "withdraw", "transfer"):
            names = args[:-1]
            missing = [n for n in names if n not in accounts]
            if missing:
                output.append(f"No account {missing[0]}")
                continue
            amount = float(args[-1])
            if action == "deposit":
                balance = deposit(accounts, names[0], amount)
                output.append(f"{names[0]}: ${balance:.2f}")
            elif action == "withdraw":
                if withdraw(accounts, names[0], amount):
                    output.append(f"{names[0]}: ${accounts[names[0]]:.2f}")
                else:
                    output.append("Not enough money")
            elif transfer(accounts, names[0], names[1], amount):
                output.append(f"Moved ${amount:.2f} from {names[0]} to {names[1]}")
            else:
                output.append("Not enough money")
        else:
            output.append("Unknown command")
    return output
